/// <summary>
///     The <c>NDX_KBVSalesVolumeTable</c> is the extension class for table <c>common</c>
/// </summary>
public class NDX_KBVSalesVolumeTable extends common
{
}

Method.Source:
/// <summary>
///    AVA <c>checkValues</c> method.
/// </summary>
/// <param name="_bvId">
///    <c>KCS_KBVBuildingProjectID</c> as type
/// </param>
/// <param name="_fstcErrorMessage">
///    <c>FormStaticTextControl</c> as type
/// </param>
/// <param name="_fgcErrorMessageBox">
///    <c>FormGroupControl</c> as type
/// </param>
/// <returns>
///    <c>boolean</c> as return value
/// </returns>
public static boolean checkValues(  KCS_KBVBuildingProjectID    _bvId, 
                                    FormStaticTextControl       _fstcErrorMessage, 
                                    FormGroupControl            _fgcErrorMessageBox )
{
    KCS_KBVPotentialSalesVolumeGLB  locKCS_KBVPotentialSalesVolumeGLB;
    NDX_KBVSalesVolumeTable         locNDX_KBVSalesVolumeTable;
    NDX_KBVSalesVolumeLine          locNDX_KBVSalesVolumeLine;

    boolean lError                      = false;

    locKCS_KBVPotentialSalesVolumeGLB   = KCS_KBVPotentialSalesVolumeGLB::find(_bvId);
    locNDX_KBVSalesVolumeTable          = NDX_KBVSalesVolumeTable::find(NoYes::Yes, _bvId);
    lError                              = (locKCS_KBVPotentialSalesVolumeGLB && !locNDX_KBVSalesVolumeTable);
    if (!lError)
    {
        lError                          = locKCS_KBVPotentialSalesVolumeGLB.KCS_KBVPotentialSalesVolume != locNDX_KBVSalesVolumeTable.AmountMST;
    }
    if (!lError)
    {
        select firstonly sum(AmountMST)
        from    locNDX_KBVSalesVolumeLine
        group by NDX_KBVSalesVolumeTable
        where   locNDX_KBVSalesVolumeLine.NDX_KBVSalesVolumeTable == locNDX_KBVSalesVolumeTable.RecId;

        lError                          = locNDX_KBVSalesVolumeLine.AmountMST != locNDX_KBVSalesVolumeTable.AmountMST;
    }

    _fgcErrorMessageBox.visible(lError);
    if (lError)
    {
        _fstcErrorMessage.text("@NDX:NXAWrongValueInformIT");
    }
    return lError;
}

/// <summary>
///    AVA <c>find</c> method.
/// </summary>
/// <param name="_gLB">
///    <c>NoYes</c> as type
/// </param>
/// <param name="_kcs_KBVBuildingProjectID">
///    <c>KCS_KBVBuildingProjectID</c> as type
/// </param>
/// <param name="_foUpdate">
///    <c>boolean</c> as type
/// </param>
/// <returns>
///    <c>NDX_KBVSalesVolumeTable</c> as return value
/// </returns>
static NDX_KBVSalesVolumeTable find(NoYes                       _gLB,
                                    KCS_KBVBuildingProjectID    _kcs_KBVBuildingProjectID,
                                    boolean                     _foUpdate = false)
{
    NDX_KBVSalesVolumeTable record;

    record.selectForUpdate(_foUpdate);

    select firstonly record
    where   record.GLB  == _gLB
        &&  record.BVID == _kcs_KBVBuildingProjectID;

    return record;
}

/// <summary>
///    AVA <c>find</c> method.
/// </summary>
/// <param name="_gLB">
///    <c>NoYes</c> as type
/// </param>
/// <param name="_kcs_KBVBuildingProjectID">
///    <c>KCS_KBVBuildingProjectID</c> as type
/// </param>
/// <param name="_doInsert">
///    <c>boolean</c> as type
/// </param>
/// <returns>
///    <c>NDX_KBVSalesVolumeTable</c> as return value
/// </returns>
static NDX_KBVSalesVolumeTable findOrCreate(NoYes                       _gLB,
                                            KCS_KBVBuildingProjectID    _kcs_KBVBuildingProjectID,
                                            boolean                     _doInsert = true )
{
    NDX_KBVSalesVolumeTable record;

    record = NDX_KBVSalesVolumeTable::find( _gLB,
                                            _kcs_KBVBuildingProjectID,
                                            true                        );
    if (!record)
    {
        record.GLB     = _gLB;
        record.BVID    = _kcs_KBVBuildingProjectID;
        if (_doInsert)
        {
            record.insert();
        }
    }

    return record;
}
